SELECT bkt, COUNT(*) n, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,{B}) bkt, a||'|'||ym||'|'||net r FROM (SELECT t.ACCOUNT_NO a, TO_CHAR(t.VM_DATE,'YYYYMM') ym, ROUND(SUM(t.DR_AMOUNT-t.CR_AMOUNT),2) net FROM {P}GL_TRANSACTIONS_DETAILS t WHERE t.STATUS<>'C' AND (t.ACCOUNT_NO LIKE '13%' OR t.ACCOUNT_NO LIKE '14%') GROUP BY t.ACCOUNT_NO, TO_CHAR(t.VM_DATE,'YYYYMM') HAVING ABS(SUM(t.DR_AMOUNT-t.CR_AMOUNT))>0.004)) GROUP BY bkt
